<script setup lang="ts">import{ref}from'vue';import{ElMessage}from'element-plus';import{searchApi}from'../api/search';import PageHeader from'../components/PageHeader.vue';import ResultTable from'../components/ResultTable.vue';const mode=ref('名称精确'),query=ref(''),ext=ref(''),min=ref(''),max=ref(''),rows=ref<any[]>([]),busy=ref(false);const modes=['名称精确','通配符','扩展名','大小范围','重复文件'];async function run(){busy.value=true;try{let r:any;if(mode.value==='重复文件')r=await searchApi.duplicates();else if(mode.value==='扩展名'){if(!ext.value)return ElMessage.warning('请输入扩展名');r=await searchApi.ext({extension:ext.value})}else if(mode.value==='大小范围'){r=await searchApi.size({minSize:Number(min.value)||0,maxSize:Number(max.value)||0})}else{if(!query.value.trim())return ElMessage.warning('请输入查找内容');r=mode.value==='名称精确'?await searchApi.name({name:query.value.trim()}):await searchApi.pattern({pattern:query.value.trim()})}const d=r.data;rows.value=Array.isArray(d)?d:(d?.results||d?.files||[])}finally{busy.value=false}}</script>
<template><PageHeader title="智能查找" description="按名称、类型与文件特征快速定位内容"/><div class="card"><div class="toolbar"><select v-model="mode" class="field"><option v-for="m in modes" :key="m">{{m}}</option></select><template v-if="mode==='扩展名'"><input v-model="ext" class="field" placeholder="例如 .pdf"></template><template v-else-if="mode==='大小范围'"><input v-model="min" class="field" type="number" placeholder="最小字节"><input v-model="max" class="field" type="number" placeholder="最大字节"></template><input v-else-if="mode!=='重复文件'" v-model="query" class="field" style="flex:1" :placeholder="mode==='通配符'?'输入通配符，如 *.pdf':'输入文件名'"><button class="btn" :disabled="busy" @click="run">{{busy?'查找中…':'开始查找'}}</button></div><div class="result-meta">查找结果 <span>{{rows.length}} 项</span></div><ResultTable :rows="rows"/></div></template>
